let databaseRun=null,databaseBytes=null;
function stopDatabaseWorkspace(){if(databaseRun){clearTimeout(databaseRun.timer);databaseRun.worker.terminate();databaseRun=null;}const run=document.getElementById('db-run');if(run)run.disabled=false;const stop=document.getElementById('db-stop');if(stop)stop.disabled=true;}
function databaseDraftKey(){return 'web-talim:database:'+activeData().assignment.draftId;}
function renderDatabaseAssignment(data){
 const a=data.assignment,panel=document.createElement('section');panel.id='panel5';panel.hidden=true;panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby','tab5');databaseBytes=null;
 panel.innerHTML=`<h2>Amaliy mashg‘ulot</h2><p>${databaseEscape(a.task)}</p><h3>Bajarish tartibi</h3><ol>${a.steps.map(s=>`<li>${databaseEscape(s)}</li>`).join('')}</ol><h3>Namuna natijasi</h3><p>${databaseEscape(a.expected)}</p>${a.mode==='sqlite'?`<p class="notice">SQLite mashq muhiti. Har Run yangi ${a.useFixture?'kutubxona demo bazasi':'bo‘sh demo baza'}dan boshlanadi. Oldingi Run o‘zgarishlari avtomatik qolmaydi. Kod brauzerda bajariladi; haqiqiy texnikum bazasiga ulanmaydi.</p>${a.useFixture?'<details><summary>Demo sxema va boshlang‘ich yozuvlar</summary><pre class="lesson-code"><code>'+databaseEscape(databaseFixture)+'</code></pre></details>':''}`:`<p class="notice">${a.mode==='postgres'?'Bu PostgreSQL va psql topshirig‘i. Lokal PostgreSQL 18, demo baza va tegishli huquqlar kerak. SQLite oynasida bajarilmaydi.':a.mode==='node'?'Bu Node.js 24 uchun kod parchasi. Tegishli driver va ochiq baza ulanishi kerak; JavaScriptni SQL oynasiga ko‘chirmang.':'Bu model yoki tahlil ishi. Sxema va yozma hisobot tayyorlang; matnni SQL sifatida bajarish talab etilmaydi.'}</p>`}<label class="lab-label" for="db-code">${a.mode==='sqlite'?'SQL kodi':a.mode==='report'?'Sxema va tahlil matni':'Kod yoki lokal buyruqlar'}</label><textarea id="db-code" class="lab-editor" spellcheck="false"></textarea><div class="lab-actions">${a.mode==='sqlite'?'<button class="cta" id="db-run" type="button" onclick="runDatabaseSQL()">▶ Run — SQLni bajarish</button><button class="retry" id="db-stop" type="button" onclick="stopDatabaseSQL()" disabled>To‘xtatish</button>':''}<button class="retry" type="button" onclick="resetDatabaseCode()">Namuna kodini tiklash</button><button class="retry" type="button" onclick="downloadDatabaseCode()">Kodni yuklab olish ↓</button></div>${a.mode==='sqlite'?'<p id="db-status" role="status">SQLni yozib, ▶ Run tugmasini bosing.</p><div id="db-results" aria-live="polite"></div><button class="retry" id="db-export" type="button" onclick="exportDatabaseFile()" disabled>Natija bazasini yuklab olish ↓</button><p class="muted">Har bir natijadan ko‘pi bilan 200 satr va 10 ta natija to‘plami ko‘rsatiladi. Bajarish uchun 8 soniyalik chegara bor. To‘xtatilgan yoki xatoli bajarishdan keyin qayta Run yangi demo bazani ochadi.</p>':''}<h3>Tekshirish mezonlari</h3>${a.criteria.map(s=>`<label class="option"><input type="checkbox" class="db-check"> ${databaseEscape(s)}</label>`).join('')}<label class="lab-label" for="db-report">Hisobot — natija, xato va xulosa</label><textarea id="db-report" class="lab-editor" spellcheck="false"></textarea><p id="db-save" class="muted" role="status">Kod va hisobot shu brauzerda saqlanadi. Amaliy ishni o‘qituvchi alohida tekshiradi.</p><div class="lab-actions"><button class="retry" type="button" onclick="downloadDatabaseReport()">Hisobotni yuklab olish ↓</button><button class="cta" type="button" onclick="openResource(3)">Test sinoviga o‘tish →</button></div><p><a href="materials/m7-database-loyiha.zip" download>Demo sxema, ma’lumotlar va yakuniy loyiha testlari ↓</a></p>`;
 document.querySelector('.article').appendChild(panel);let saved={};try{saved=JSON.parse(localStorage.getItem(databaseDraftKey())||'{}');}catch(e){}
 document.getElementById('db-code').value=saved.code??a.code;document.getElementById('db-report').value=saved.report??'';panel.querySelectorAll('.db-check').forEach((x,i)=>x.checked=!!saved.checks?.[i]);panel.querySelectorAll('textarea,input').forEach(x=>x.addEventListener('input',saveDatabaseWork));
}
function saveDatabaseWork(){try{localStorage.setItem(databaseDraftKey(),JSON.stringify({code:document.getElementById('db-code').value,report:document.getElementById('db-report').value,checks:[...document.querySelectorAll('.db-check')].map(x=>x.checked)}));document.getElementById('db-save').textContent='Shu brauzerda saqlandi; boshqa qurilmaga avtomatik ko‘chmaydi.';}catch(e){document.getElementById('db-save').textContent='Saqlash mavjud emas; kod va hisobotni yuklab oling.';}}
function databaseDownload(content,name,type='text/plain;charset=utf-8'){const u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function downloadDatabaseCode(){databaseDownload(document.getElementById('db-code').value,`m7-${currentLesson}.${activeData().assignment.mode==='sqlite'?'sql':activeData().assignment.mode==='node'?'js':'txt'}`);}
function downloadDatabaseReport(){databaseDownload(document.getElementById('db-report').value,`m7-${currentLesson}-hisobot.txt`);}
function resetDatabaseCode(){stopDatabaseWorkspace();document.getElementById('db-code').value=activeData().assignment.code;saveDatabaseWork();databaseBytes=null;const out=document.getElementById('db-results');if(out)out.replaceChildren();const button=document.getElementById('db-export');if(button)button.disabled=true;}
function stopDatabaseSQL(){stopDatabaseWorkspace();document.getElementById('db-status').textContent='Bajarish to‘xtatildi. Qayta Run yangi demo bazadan boshlaydi.';}
function runDatabaseSQL(){
 const a=activeData().assignment;if(a.mode!=='sqlite')return;stopDatabaseWorkspace();saveDatabaseWork();const code=document.getElementById('db-code').value;
 if(code.length>50000){document.getElementById('db-status').textContent='SQL kodi 50 000 belgidan oshmasin.';return;}
 databaseBytes=null;document.getElementById('db-export').disabled=true;document.getElementById('db-results').replaceChildren();document.getElementById('db-run').disabled=true;document.getElementById('db-stop').disabled=false;document.getElementById('db-status').textContent='SQLite yuklanmoqda va SQL bajarilmoqda…';
 let worker;try{worker=new Worker('database-sql-worker.js');}catch(e){stopDatabaseWorkspace();document.getElementById('db-status').textContent='SQL muhitini ochib bo‘lmadi: '+e.message;return;}
 const finish=message=>{stopDatabaseWorkspace();document.getElementById('db-status').textContent=message;};
 const timer=setTimeout(()=>finish('8 soniyalik chegara tugadi. So‘rovni qisqartiring va qayta sinang.'),8000);databaseRun={worker,timer};
 worker.onerror=event=>finish('SQL muhitini yuklash xatosi. Sahifani qayta oching yoki yuklab olinadigan lokal loyihadan foydalaning.');
 worker.onmessage=event=>{
  if(databaseRun?.worker!==worker)return;const data=event.data;
  if(data.type==='error'){finish('SQL xatosi: '+data.message);return;}if(data.type!=='done')return;
  databaseBytes=data.bytes;document.getElementById('db-export').disabled=false;
  const holder=document.getElementById('db-results');
  for(const [i,result] of data.results.entries()){
   const heading=document.createElement('h3');heading.textContent=`${i+1}-natija · ${result.values.length} satr${result.truncated?' · ko‘rinish chegaralangan':''}`;holder.appendChild(heading);
   const wrap=document.createElement('div');wrap.className='table-scroll';const table=document.createElement('table'),thead=document.createElement('thead'),header=document.createElement('tr');
   for(const name of result.columns){const th=document.createElement('th');th.textContent=name;header.appendChild(th);}thead.appendChild(header);table.appendChild(thead);
   const tbody=document.createElement('tbody');for(const row of result.values){const tr=document.createElement('tr');for(const value of row){const td=document.createElement('td');td.textContent=value===null?'NULL':String(value);tr.appendChild(td);}tbody.appendChild(tr);}table.appendChild(tbody);wrap.appendChild(table);holder.appendChild(wrap);
  }
  finish(`SQLite ${data.version}: SQL bajarildi.${data.results.length?'':' Natija qaytaruvchi SELECT yo‘q.'}`);
 };
 worker.postMessage({type:'run',code,fixture:a.useFixture?databaseFixture:''});
}
function exportDatabaseFile(){if(databaseBytes)databaseDownload(databaseBytes,`m7-${currentLesson}-demo.sqlite`,'application/vnd.sqlite3');}
